/* 1. CRC 挂在 AHB 上，时钟使能方式和其它外设不同 */
RCC_AHBPeriphClockCmd(RCC_AHBPeriph_CRC, ENABLE);

/* 2. 算新数据前复位，否则会接着上一段的结果继续算 */
CRC_ResetDR();

/* 3. 累加数据 */
CRC_CalcBlockCRC((uint32_t*)buf, len / 4);

/* 4. 取结果 */
uint32_t crc = CRC_GetCRC();

/* 逐字节数据必须自己拼成 32 位字；长度不足 4 的倍数要补齐 */
uint32_t crc32_of_bytes(const uint8_t *buf, uint32_t len)
{
  uint32_t i = 0;
  uint32_t word;

  CRC_ResetDR();

  while (i + 4 <= len)
  {
    /* 小端拼字，与 STM32 内存布局一致 */
    word = (uint32_t)buf[i]
         | ((uint32_t)buf[i + 1] << 8)
         | ((uint32_t)buf[i + 2] << 16)
         | ((uint32_t)buf[i + 3] << 24);
    CRC_CalcCRC(word);
    i += 4;
  }

  /* 尾部不足 4 字节：用 0xFF 补齐（收发两端必须约定一致） */
  if (i < len)
  {
    word = 0xFFFFFFFF;
    uint8_t *p = (uint8_t *)&word;
    uint32_t k = 0;
    while (i < len)
    {
      p[k++] = buf[i++];
    }
    CRC_CalcCRC(word);
  }

  return CRC_GetCRC();
}

uint32_t data[64];   /* 必须是 4 字节对齐的 uint32_t 数组 */
uint32_t crc;

RCC_AHBPeriphClockCmd(RCC_AHBPeriph_CRC, ENABLE);

CRC_ResetDR();

/* 长度单位是「字数」：数组有 64 个字就传 64 */
crc = CRC_CalcBlockCRC(data, 64);

